      "「かぶるかかぶらないか」——「か～か」重複使用表示「戴或不戴」兩者選一，根據天氣決定，為正解。",
      "「かぶらないが」的「が」是接續助詞，不能用來表達「A或B」的擇一語意，錯誤。"
